  protected readonly shown = computed(() => {
    const visible = this.visible();
    return this.people().filter((p) => (this.showRetired() || !p.retired) && (visible === null || visible.has(p.id)));
  });
  /**
   * The ids of the people a restricted user may see listed: the person with their name and the leads and members of
   * the crews that person leads or belongs to; none without such a person. Null (everyone) for any other role.
   * People this screen added since the sheet was last read stay listed until it is read again.
   */
  private readonly visible = computed(() => {
    if (this.role() !== 'restricted') return null;
    const me = this.me();
    if (me === null) return new Set<number>(this.addedHere());
    const ids = new Set<number>([me.id, ...this.addedHere()]);
    for (const c of this.crews()) {
      const crew = [...(c.lead ? [c.lead] : []), ...c.members];
      if (crew.some((w) => w.personId === me.id)) crew.forEach((w) => ids.add(w.personId));
    }
    return ids;
  });
  protected readonly sortKeys = SORT_KEYS;
  /** How this user's screen orders the listed people; only the screen, never the list order itself. */
  protected readonly sortKey = signal<SortKey>('added');
  /** The listed people as the screen orders them; people with equal keys keep their list order. */
  protected readonly sorted = computed(() => sortPeople(this.shown(), this.sortKey()));
  protected readonly statusCounts = computed(() => statusCounts(this.people()));
  protected readonly claimedTotal = computed(() =>
    (this.people().reduce((sum, p) => sum + cents(p.claimed), 0) / 100).toFixed(2),
  );
  /** Everyone's due-total added up, trimmed (see {@link trimmedSum}); a person showing n/a is skipped. */
  protected readonly dueTotal = computed(() => (dueTotalOf(this.people()) / 100).toFixed(2));
  /** Everyone's settled-total added up, not trimmed. */
  protected readonly settledTotal = computed(() =>
    (this.people().reduce((sum, p) => sum + cents(p.settledTotal), 0) / 100).toFixed(2),
  );
  /** Everyone's open-total added up, not trimmed. */
  protected readonly openTotal = computed(() =>
    (this.people().reduce((sum, p) => sum + cents(p.openTotal), 0) / 100).toFixed(2),
  );

  /** Everyone's due aged 0 to 30 days added up, not trimmed. */
  protected readonly aged0to30 = computed(() =>
    (this.people().reduce((sum, p) => sum + cents(p.aged0to30), 0) / 100).toFixed(2),
  );
  /** Everyone's due aged 31 to 60 days added up, not trimmed. */
  protected readonly aged31to60 = computed(() =>
    (this.people().reduce((sum, p) => sum + cents(p.aged31to60), 0) / 100).toFixed(2),
  );
  /** Everyone's due aged 61 or more days added up, not trimmed. */
  protected readonly aged61 = computed(() =>
    (this.people().reduce((sum, p) => sum + cents(p.aged61), 0) / 100).toFixed(2),
  );

  /** Everyone's cut total added up, not trimmed. */
  protected readonly cutTotal = computed(() =>
    (this.people().reduce((sum, p) => sum + (this.personCuts().get(p.id) ?? 0), 0) / 100).toFixed(2),
  );

  /** Each person's patrons, each as their name with the grade in force today and share, sorted by name and comma separated, and their
   *  backing: each patron's recent settled figure (see {@link Person.recentSettled}) times their share
   *  divided by 100, added up and rounded half to even (see {@link patronShares}). */
  protected readonly patronage = computed(() => {
    const byId = new Map(this.people().map((p) => [p.id, p]));
    return new Map(
      this.people().map((p) => {
        const patrons = p.patrons.map((id) => byId.get(id)).filter((q): q is Person => q !== undefined);
        const shares = patronShares(patrons.length);
        const named = patrons.map((q, i) => ({ name: q.name, grade: q.grade, share: shares[i] }));
        const names = named
          .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
          .map((n) => `${n.name} (${n.grade}) ${(n.share / 100).toFixed(2)}`)
        this.bulkRetire = bulkRetire;
        this.service = service;
        this.imports = imports;
        this.transfers = transfers;
        this.merges = merges;
        this.bulkGrade = bulkGrade;
        this.claims = claims;
        this.rates = rates;
        this.statements = statements;
    }

    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String sheet = sheetId.trim();
        Map<Long, List<Claim>> bySheet = claims.bySheet(sheet);
        RateTable table = rates.table(sheet);
        Map<Long, Statements> stated = statements.bySheet(sheet);
        Map<Long, List<Long>> patrons = service.patronsBySheet(sheet);
        Set<Long> clashing = service.clashing(sheet);
        Map<Long, List<PersonSnapshot>> snapshots = service.snapshotsBySheet(sheet);
        return service.list(sheet).stream()
                .map(p -> PersonView.of(p, bySheet.getOrDefault(p.getId(), List.of()), table,
                        stated.getOrDefault(p.getId(), Statements.NONE),
                        patrons.getOrDefault(p.getId(), List.of()), clashing.contains(p.getId()),
                        snapshots.getOrDefault(p.getId(), List.of()))).toList();
    }

    /** The people of the sheet's tree whose name or an alias contains the text (see {@link PersonService#search}). */
    @GetMapping("/search")
    public List<PersonService.Found> search(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestParam(defaultValue = "") @Size(max = 200) String text) {
        return service.search(sheetId.trim(), text);
    }

    @PostMapping
    public PersonView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody PersonForm form) {
        String sheet = sheetId.trim();
        return PersonView.of(service.add(sheet, user.trim(), form.name(), form.grade(), form.termsDays(),
                form.termsFrom(), form.contactKey(), form.tags()), List.of(),
                rates.table(sheet), Statements.NONE, List.of(), false, List.of());
    }

    /** Restore a DELETED claim to a DRAFT, on the sheet's today it was deleted. */
    @PostMapping("/claims/{claimId}/restore")
    public PersonView restore(@PathVariable @NotBlank @Size(max = 100) String sheetId,
